def names():
    for case, rel, content, note in NAME_CASES:
        write(f"p44/name/{case}/{rel}", content, "2 name", note)
        write(f"p44/name/{case}/control.txt", content, "2 name control", f"control for {rel}")
    write("p44/name/cargo-mod/Cargo.lock", CARGO_LOCK_MOD, "2 name", "Cargo.lock modified (subdirectory)")
    write("p44/name/cargo-mod/control.txt", CARGO_LOCK_MOD, "2 name control", "control for modified Cargo.lock")
    write("Cargo.lock", CARGO_LOCK, "2 name", "Cargo.lock new at repository root")
    for rel, note in ADV:
        write(f"p44/adv/{rel}", RS_BODY, "2 name adversarial", note)


def body(ext):
    b = {
        "go": "package gen\n\nfunc Answer() int {\n\ttotal := 0\n\tfor i := 0; i < 10; i++ {\n\t\ttotal += i\n\t}\n\treturn total\n}\n\nfunc Other() int {\n\treturn 1\n}\n",
        "rs": RS_BODY,
        "js": "function answer() {\n  var total = 0;\n  for (var i = 0; i < 10; i++) {\n    total += i;\n  }\n  return total;\n}\n\nfunction other() {\n  return 1;\n}\n\nmodule.exports = { answer: answer, other: other };\n",
        "ts": "export function answer(): number {\n  let total = 0;\n  for (let i = 0; i < 10; i++) {\n    total += i;\n  }\n  return total;\n}\n\nexport function other(): number {\n  return 1;\n}\n",
        "css": "a {\n  color: red;\n}\n\nb {\n  color: blue;\n}\n\ni {\n  color: green;\n}\n",
        "py": "def answer():\n    total = 0\n    for i in range(10):\n        total += i\n    return total\n\n\ndef other():\n    return 1\n\n\nprint(answer())\n",
        "c": "#include <stdio.h>\n\nint answer(void) {\n  int total = 0;\n  for (int i = 0; i < 10; i++) {\n    total += i;\n  }\n  return total;\n}\n\nint main(void) {\n  printf(\"%d\\n\", answer());\n  return 0;\n}\n",
        "h": "#ifndef P44_H\n#define P44_H\n\nint answer(void);\nint other(void);\nint third(void);\nint fourth(void);\nint fifth(void);\nint sixth(void);\nint seventh(void);\n\n#endif\n",
        "java": "package p44;\n\npublic class Gen {\n  public static int answer() {\n    int total = 0;\n    for (int i = 0; i < 10; i++) {\n      total += i;\n    }\n    return total;\n  }\n}\n",
        "rb": "module P44\n  def self.answer\n    total = 0\n    10.times { |i| total += i }\n    total\n  end\nend\n\nputs P44.answer\n",
        "cs": "namespace P44 {\n  public class Gen {\n    public static int Answer() {\n      return 45;\n    }\n  }\n}\n",
        "dart": "int answer() {\n  var total = 0;\n  for (var i = 0; i < 10; i++) {\n    total += i;\n  }\n  return total;\n}\n",
        "proto": "syntax = \"proto3\";\n\npackage p44;\n\nmessage Answer {\n  int32 value = 1;\n}\n",
        "toml": "version = 4\n\n[[package]]\nname = \"anyhow\"\nversion = \"1.0.86\"\n\n[[package]]\nname = \"p44-probe\"\nversion = \"0.1.0\"\n",
        "yml": "http_interactions:\n- request:\n    method: get\n    uri: https://example.com/\n  response:\n    status:\n      code: 200\n    body:\n      string: ok\n",
    }
    return b[ext]


def content():
    c = "3 content"

    def pair(name, ext, gen, note, ctl=None):
        write(f"p44/content/{name}.{ext}", gen, c, note)

    def ctl(ext):
        write(f"p44/content/control.{ext}", body(ext), "3 content control", f"control: .{ext} without header")

    for ext in ["go", "rs", "js", "ts", "css", "py", "c", "h", "java", "rb", "cs", "dart", "proto", "toml", "yml"]:
        ctl(ext)

    # Go
    pair("go_code_generated", "go", "// Code generated by protoc-gen-go. DO NOT EDIT.\n\n" + body("go"), "generated_go?: // Code generated in first 40 lines")
    pair("go_code_generated_line30", "go", body("go") + "\n" * 16 + "// Code generated by hand, line 30.\n" + "func Late() int {\n\treturn 2\n}\n", "generated_go?: marker at line 30 of a hand-written file")
    pair("go_thrift", "go", "// Autogenerated by Thrift Compiler (0.19.0)\n\n" + body("go"), "generated_apache_thrift?")
    # Rust: no rule in generated.rb, try the headers authors and tools write
