    pair("rs_at_generated", "rs", "// @generated\n\n" + RS_BODY, "no rule for .rs: @generated")
    pair("rs_cargo_header", "rs", "// This file is automatically @generated by Cargo.\n// It is not intended for manual editing.\n\n" + RS_BODY, "no rule for .rs: Cargo lock header")
