    pair("rs_bindgen", "rs", "/* automatically generated by rust-bindgen 0.69.4 */\n\n" + RS_BODY, "no rule for .rs: bindgen header")
    pair("rs_protobuf", "rs", "// Generated by the protocol buffer compiler.  DO NOT EDIT!\n\n" + RS_BODY, "no rule for .rs: protoc header (rule is by extension)")
