    pair("rs_autogenerated_tag", "rs", "// <auto-generated>\n//   This code was generated by a tool.\n// </auto-generated>\n\n" + RS_BODY, "no rule for .rs: .NET auto-generated tag")
    pair("toml_cargo_header", "toml", "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n" + body("toml"), "Cargo.lock header under a neutral .toml name")
    # JS
    pair("js_generated_by", "js", "// Generated by hand, actually\n" + body("js"), "compiled_coffeescript?: first line starts with // Generated by ")
    pair("js_coffee", "js", "// Generated by CoffeeScript 1.12.7\n" + body("js"), "compiled_coffeescript?")
    pair("js_pegjs", "js", "/*\n * Generated by PEG.js 0.10.0.\n *\n * http://pegjs.org/\n */\n" + body("js"), "generated_parser?")
    pair("js_jison", "js", "/* parser generated by jison 0.4.18 */\n" + body("js"), "generated_jison?")
    pair("js_protobuf", "js", "// source: x.proto\n/**\n * @fileoverview\n * @enhanceable\n */\n// GENERATED CODE -- DO NOT EDIT!\n\n" + body("js"), "generated_javascript_protocol_buffer?: line 6")
    pair("js_haxe", "js", "// Generated by Haxe 4.3.1\n" + body("js"), "generated_haxe? (also matches coffeescript rule)")
    pair("js_haxe_line2", "js", "'use strict';\n/* Generated by Haxe 4.3.1 */\n" + body("js"), "generated_haxe?: within first 3 lines")
    pair("js_thrift", "js", "//\n// Autogenerated by Thrift Compiler (0.19.0)\n//\n" + body("js"), "generated_apache_thrift?")
    pair("js_sourcemap", "js", body("js") + "//# sourceMappingURL=js_sourcemap.js.map\n", "has_source_map?: last line")
    pair("js_sourceurl_anywhere", "js", body("js") + "var s = 'x sourceURL=y';\n", "has_source_map?: sourceURL= anywhere in the last 2 lines")
    long = "var a=function(b){return b+1};" * 8
    pair("js_minified", "js", (long + "\n") * 6, "minified_files?: average line length > 110")
    pair("js_one_long_line", "js", body("js") + "// " + "x" * 3000 + "\n", "minified_files?: normal code plus one 3000-char comment line (average > 110)")
    # CSS
    pair("css_minified", "css", ("a{color:red}b{color:blue}i{color:green}" * 6 + "\n") * 4, "minified_files?")
    pair("css_sourcemap", "css", body("css") + "/*# sourceMappingURL=css_sourcemap.css.map */\n", "has_source_map?")
