    write("p44/content/ppport/ppport.h", "/*\n" + " * filler\n" * 7 + " * Automatically created by Devel::PPPort running under perl 5.036000.\n */\n" + body("h"), c, "generated_perl_ppport_header?: line 9")
    # HTML
    html_body = "<body>\n<p>hello</p>\n<p>world</p>\n</body>\n</html>\n"
    write("p44/content/control.html", "<!DOCTYPE html>\n<html>\n<head>\n<title>p44</title>\n</head>\n" + html_body, "3 content control", "control: .html without generator")
    pair("html_meta_generator", "html", "<!DOCTYPE html>\n<html>\n<head>\n<title>p44</title>\n<meta name=\"generator\" content=\"makeinfo 4.8\" />\n</head>\n" + html_body, "generated_html?: meta generator makeinfo")
    pair("html_meta_generator_other", "html", "<!DOCTYPE html>\n<html>\n<head>\n<title>p44</title>\n<meta name=\"generator\" content=\"rustdoc\" />\n</head>\n" + html_body, "not a rule: meta generator rustdoc")
    pair("html_pkgdown", "html", "<!-- Generated by pkgdown: do not edit by hand -->\n<!DOCTYPE html>\n<html>\n<head>\n<title>p44</title>\n</head>\n" + html_body, "generated_html?: pkgdown")
    pair("html_doxygen", "html", "<!DOCTYPE html>\n<html>\n<head>\n<title>p44</title>\n</head>\n<!-- Generated by Doxygen 1.9.8 -->\n" + html_body, "generated_html?: doxygen")
    # YAML (VCR)
    pair("yml_vcr", "yml", body("yml") + "recorded_at: Mon, 01 Jan 2024 00:00:00 GMT\nrecorded_with: VCR 6.1.0\n", "vcr_cassette?: recorded_with: VCR on the last line")
    pair("yml_vcr_comment", "yml", body("yml") + "# recorded_with: VCR\n", "vcr_cassette?: marker as a trailing comment")
    # XML .NET docfile
