{"base": base, "kinds": kinds, "names": names, "content": content}[mode]()

with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", f"manifest-{mode}.tsv"), "w") as f:
    for case, rel, note in manifest:
        f.write(f"{case}\t{rel}\t{note}\n")
print(f"{mode}: {len(manifest)} entries")
